namespace sv_e65c2a6c8c5d4f0b9c641998a3794740.Client.Models;

public sealed record ShipmentDetails(
    string TrackingNumber,
    string Status,
    string Location,
    DateTimeOffset EstimatedDelivery,
    IReadOnlyList<StatusUpdate> StatusUpdates);

public sealed record StatusUpdate(
    string Status,
    string Location,
    DateTimeOffset Timestamp);

using sv_e65c2a6c8c5d4f0b9c641998a3794740.Client.Models;

namespace sv_e65c2a6c8c5d4f0b9c641998a3794740.Client.Services;

public interface IShipmentService
{
    Task<ShipmentDetails?> GetShipmentAsync(string trackingNumber, CancellationToken ct);
}

using System.Net.Http.Json;
using sv_e65c2a6c8c5d4f0b9c641998a3794740.Client.Models;

namespace sv_e65c2a6c8c5d4f0b9c641998a3794740.Client.Services;

public sealed class HttpShipmentService(HttpClient httpClient) : IShipmentService
{
    public async Task<ShipmentDetails?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        var response = await httpClient.GetAsync($"api/shipments/{Uri.EscapeDataString(trackingNumber)}", ct);

        if (response.StatusCode == System.Net.HttpStatusCode.NotFound)
            return null;

        response.EnsureSuccessStatusCode();

        return await response.Content.ReadFromJsonAsync<ShipmentDetails>(ct);
    }
}

using sv_e65c2a6c8c5d4f0b9c641998a3794740.Client.Models;
using sv_e65c2a6c8c5d4f0b9c641998a3794740.Client.Services;

namespace sv_e65c2a6c8c5d4f0b9c641998a3794740.Services;

public sealed class ShipmentService : IShipmentService
{
    private static readonly Dictionary<string, ShipmentDetails> SeedData = new(StringComparer.OrdinalIgnoreCase)
    {
        ["TRK-1001"] = new ShipmentDetails(
            TrackingNumber: "TRK-1001",
            Status: "In Transit",
            Location: "Chicago, IL",
            EstimatedDelivery: new DateTimeOffset(2026, 7, 5, 17, 0, 0, TimeSpan.Zero),
            StatusUpdates: [
                new StatusUpdate("Order Placed", "New York, NY", new DateTimeOffset(2026, 6, 28, 10, 0, 0, TimeSpan.Zero)),
                new StatusUpdate("Picked Up", "New York, NY", new DateTimeOffset(2026, 6, 29, 8, 30, 0, TimeSpan.Zero)),
                new StatusUpdate("In Transit", "Chicago, IL", new DateTimeOffset(2026, 6, 30, 14, 15, 0, TimeSpan.Zero)),
            ]),

        ["TRK-2002"] = new ShipmentDetails(
            TrackingNumber: "TRK-2002",
            Status: "Delivered",
            Location: "San Francisco, CA",
            EstimatedDelivery: new DateTimeOffset(2026, 6, 30, 12, 0, 0, TimeSpan.Zero),
            StatusUpdates: [
                new StatusUpdate("Order Placed", "Seattle, WA", new DateTimeOffset(2026, 6, 25, 9, 0, 0, TimeSpan.Zero)),
                new StatusUpdate("Picked Up", "Seattle, WA", new DateTimeOffset(2026, 6, 26, 7, 45, 0, TimeSpan.Zero)),
                new StatusUpdate("In Transit", "Portland, OR", new DateTimeOffset(2026, 6, 27, 11, 0, 0, TimeSpan.Zero)),
                new StatusUpdate("Out for Delivery", "San Francisco, CA", new DateTimeOffset(2026, 6, 29, 8, 0, 0, TimeSpan.Zero)),
                new StatusUpdate("Delivered", "San Francisco, CA", new DateTimeOffset(2026, 6, 29, 14, 22, 0, TimeSpan.Zero)),
            ]),

        ["TRK-3003"] = new ShipmentDetails(
            TrackingNumber: "TRK-3003",
            Status: "Out for Delivery",
            Location: "Austin, TX",
            EstimatedDelivery: new DateTimeOffset(2026, 7, 1, 18, 0, 0, TimeSpan.Zero),
            StatusUpdates: [
                new StatusUpdate("Order Placed", "Miami, FL", new DateTimeOffset(2026, 6, 27, 14, 0, 0, TimeSpan.Zero)),
                new StatusUpdate("Picked Up", "Miami, FL", new DateTimeOffset(2026, 6, 28, 6, 0, 0, TimeSpan.Zero)),
                new StatusUpdate("In Transit", "Houston, TX", new DateTimeOffset(2026, 6, 29, 20, 30, 0, TimeSpan.Zero)),
                new StatusUpdate("Out for Delivery", "Austin, TX", new DateTimeOffset(2026, 7, 1, 7, 15, 0, TimeSpan.Zero)),
            ]),
    };

    public async Task<ShipmentDetails?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        await Task.Delay(1500, ct);

        SeedData.TryGetValue(trackingNumber, out var shipment);
        return shipment;
    }
}

@page "/shipments/{TrackingNumber}"
@rendermode InteractiveAuto
@using sv_e65c2a6c8c5d4f0b9c641998a3794740.Client.Models
@using sv_e65c2a6c8c5d4f0b9c641998a3794740.Client.Services
@inject IShipmentService ShipmentService
@inject ILogger<ShipmentTracker> Logger
@implements IDisposable

<PageTitle>Shipment @TrackingNumber</PageTitle>

<h3>Shipment Tracker</h3>

@if (_loading)
{
    <div class="alert alert-info" role="status">
        <span class="spinner-border spinner-border-sm me-2" aria-hidden="true"></span>
        Loading shipment <strong>@TrackingNumber</strong>&hellip;
    </div>
}
else if (_errorMessage is not null)
{
    <div class="alert alert-danger" role="alert">
        <p class="mb-2">@_errorMessage</p>
        <button class="btn btn-outline-danger btn-sm" @onclick="RetryAsync">Retry</button>
    </div>
}
else if (_shipment is null)
{
    <div class="alert alert-warning" role="alert">
        No shipment found for tracking number <strong>@TrackingNumber</strong>.
    </div>
}
else
{
    <div class="card mb-3">
        <div class="card-body">
            <h5 class="card-title">@_shipment.TrackingNumber</h5>
            <p><strong>Status:</strong> @_shipment.Status</p>
            <p><strong>Location:</strong> @_shipment.Location</p>
            <p><strong>Estimated Delivery:</strong> @_shipment.EstimatedDelivery.ToString("f")</p>
        </div>
    </div>

    <h5>Status History</h5>
    <table class="table table-striped">
        <thead>
            <tr>
                <th>Time</th>
                <th>Status</th>
                <th>Location</th>
            </tr>
        </thead>
        <tbody>
            @foreach (var update in _shipment.StatusUpdates)
            {
                <tr>
                    <td>@update.Timestamp.ToString("g")</td>
                    <td>@update.Status</td>
                    <td>@update.Location</td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    [Parameter]
    public string TrackingNumber { get; set; } = default!;

    private ShipmentDetails? _shipment;
    private bool _loading;
    private string? _errorMessage;
    private CancellationTokenSource? _cts;

    protected override Task OnParametersSetAsync() => LoadShipmentAsync();

    private async Task LoadShipmentAsync()
    {
        // Cancel any in-flight request when the tracking number changes
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = new CancellationTokenSource();
        var ct = _cts.Token;

        _shipment = null;
        _errorMessage = null;
        _loading = true;

        try
        {
            _shipment = await ShipmentService.GetShipmentAsync(TrackingNumber, ct);
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested)
        {
            // Navigation changed the tracking number; silently abandon this load.
            return;
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (TaskCanceledException ex) when (ex.InnerException is TimeoutException)
        {
            Logger.LogError(ex, "Timeout loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "Something went wrong while loading shipment details. Please try again.";
        }
        finally
        {
            _loading = false;
        }
    }

    private Task RetryAsync() => LoadShipmentAsync();

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

